import (
	"fmt"
)

resp, err := client.Carts().GetCart(ctx, "cart-7f3a9c2e1b", nil)
if err != nil {
	log.Fatal(err)
}
cart := resp.Map().(map[string]any)["cart"].(map[string]any)
for _, row := range cart["items"].([]any) {
	item := row.(map[string]any)
	fmt.Println(item["id"], item["product"].(map[string]any)["name"], item["quantity"], item["pricing"].(map[string]any)["total"])
}
totals := cart["totals"].(map[string]any)
fmt.Println(totals["subtotal"], cart["shipping"].(map[string]any)["shipping_tax"], totals["grand_total"])

